"""Counting core: decode, count, rank and format. No argparse, no stdout or stderr access."""

import json
import os
import re
from collections import Counter
from dataclasses import dataclass


@dataclass
class WordStats:
    lines: int
    words: int
    chars: int
    top: list[tuple[str, int]]


def decode_file(path: str | os.PathLike[str]) -> str:
    with open(path, "rb") as f:
        return f.read().decode("utf-8-sig")


def count_text(text: str, top_n: int) -> WordStats:
    tokens = re.findall(r"[a-z0-9]+", text.lower())
    counts = Counter(tokens)
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return WordStats(
        lines=len(text.splitlines()),
        words=len(tokens),
        chars=len(text),
        top=ranked[:top_n],
    )


def format_text(result: WordStats) -> str:
    top = " ".join(f"{word}={count}" for word, count in result.top)
    top_line = f"top: {top}" if result.top else "top:"
    return (
        f"lines: {result.lines}\n"
        f"words: {result.words}\n"
        f"chars: {result.chars}\n"
        f"{top_line}\n"
    )


def format_json(result: WordStats) -> str:
    obj = {
        "lines": result.lines,
        "words": result.words,
        "chars": result.chars,
        "top": [{"word": word, "count": count} for word, count in result.top],
    }
    return json.dumps(obj) + "\n"
